const markDepositsOrphaned = `-- name: MarkDepositsOrphaned :many
UPDATE chain.deposits
SET status = 'orphaned', orphaned_at_block = $4, version = version + 1, updated_at = now()
WHERE tenant_id = $1 AND chain_id = $2 AND block_number >= $3
  AND status IN ('detected', 'confirming')
RETURNING id, tenant_id, chain_id, tx_hash, log_index, address, account_id, asset, amount, block_number, block_hash, confirmations, status, orphaned_at_block, credited_at, correlation_id, version, created_at, updated_at, fee, credited_amount, reorged_at_block, reversal_requested_by, reversal_requested_at, reversal_note, reversal_error, reversed_at
`

type MarkDepositsOrphanedParams struct {
	TenantID        string
	ChainID         int64
	BlockNumber     int64
	OrphanedAtBlock *int64
}

// Everything not yet credited in the abandoned blocks. Credited deposits are
// deliberately excluded: undoing those is the manual `reversed` path.
func (q *Queries) MarkDepositsOrphaned(ctx context.Context, arg MarkDepositsOrphanedParams) ([]ChainDeposit, error) {
	rows, err := q.db.Query(ctx, markDepositsOrphaned,
		arg.TenantID,
		arg.ChainID,
		arg.BlockNumber,
		arg.OrphanedAtBlock,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ChainDeposit{}
	for rows.Next() {
		var i ChainDeposit
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.ChainID,
			&i.TxHash,
			&i.LogIndex,
			&i.Address,
			&i.AccountID,
			&i.Asset,
			&i.Amount,
			&i.BlockNumber,
			&i.BlockHash,
			&i.Confirmations,
			&i.Status,
			&i.OrphanedAtBlock,
			&i.CreditedAt,
			&i.CorrelationID,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Fee,
			&i.CreditedAmount,
			&i.ReorgedAtBlock,
			&i.ReversalRequestedBy,
			&i.ReversalRequestedAt,
			&i.ReversalNote,
			&i.ReversalError,
			&i.ReversedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

