const upsertBlock = `-- name: UpsertBlock :exec
INSERT INTO chain.blocks (tenant_id, chain_id, number, hash, parent_hash)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (tenant_id, chain_id, number) DO UPDATE
SET hash = excluded.hash, parent_hash = excluded.parent_hash, seen_at = now()
`

type UpsertBlockParams struct {
	TenantID   string
	ChainID    int64
	Number     int64
	Hash       string
	ParentHash string
}

// A rescan after a reorg writes a different hash at the same height, so the
// conflict target is the height and the hash is overwritten.
func (q *Queries) UpsertBlock(ctx context.Context, arg UpsertBlockParams) error {
	_, err := q.db.Exec(ctx, upsertBlock,
		arg.TenantID,
		arg.ChainID,
		arg.Number,
		arg.Hash,
		arg.ParentHash,
	)
	return err
}

